#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cerrno>
#include <limits>

static void reverse_complement(unsigned char* first,
                               unsigned char* last,
                               const unsigned char* complement) {
    while (first < last) {
        while (first < last && *first <= ' ')
            ++first;
        while (first < last && last[-1] <= ' ')
            --last;

        if (first == last)
            break;

        --last;
        const unsigned char base = *first;
        *first++ = complement[*last];
        *last = complement[base];
    }
}

