    const char* complements = "TGCAAKYWSRMBDHVN";
    for (std::size_t i = 0; bases[i]; ++i) {
        const unsigned char base = static_cast<unsigned char>(bases[i]);
        const unsigned char value = static_cast<unsigned char>(complements[i]);
        complement[base] = value;
        complement[base + ('a' - 'A')] = value;
    }

    std::size_t capacity = 1024 * 1024;
    std::size_t size = 0;
    auto* data = static_cast<unsigned char*>(std::malloc(capacity));
    if (!data)
        return 1;

    for (;;) {
        if (size == capacity) {
            if (capacity > std::numeric_limits<std::size_t>::max() / 2) {
                std::free(data);
                return 1;
            }

            capacity *= 2;
            void* grown = std::realloc(data, capacity);
            if (!grown) {
                std::free(data);
                return 1;
            }
            data = static_cast<unsigned char*>(grown);
        }

        const std::size_t count =
            std::fread(data + size, 1, capacity - size, stdin);
        size += count;

        if (count == 0) {
            if (std::ferror(stdin)) {
                std::free(data);
                return 1;
            }
            break;
        }
        if (std::feof(stdin))
            break;
    }

    unsigned char* const finish = data + size;
    unsigned char* header = data;

