        auto* newline = static_cast<unsigned char*>(
            std::memchr(header, '\n', static_cast<std::size_t>(finish - header)));
        if (!newline)
            break;

        unsigned char* sequence = newline + 1;
        unsigned char* next_header = finish;
        unsigned char* search = sequence;

        while (search < finish) {
            auto* candidate = static_cast<unsigned char*>(
                std::memchr(search, '>',
                            static_cast<std::size_t>(finish - search)));
            if (!candidate)
                break;

            if (candidate[-1] == '\n') {
                next_header = candidate;
                break;
            }
            search = candidate + 1;
        }

        reverse_complement(sequence, next_header, complement);
        header = next_header;
    }

    std::size_t written = 0;
    while (written < size) {
        const std::size_t count =
            std::fwrite(data + written, 1, size - written, stdout);
        if (count == 0) {
            std::free(data);
            return 1;
        }
        written += count;
    }

    std::free(data);
    return std::fflush(stdout) == 0 ? 0 : 1;
}

